package payflow

import (
	"encoding/json"
	"strings"
	"testing"
)

const validConfig = `{
  "flags": [
    {
      "key": "disabled-flag",
      "enabled": false,
      "default": true,
      "rules": [
        {
          "id": "r1",
          "value": false,
          "conditions": [
            {"attribute": "country", "op": "eq", "value": "CN"}
          ]
        }
      ]
    },
    {
      "key": "eq-flag",
      "enabled": true,
      "default": false,
      "rules": [
        {
          "id": "cn-pro",
          "value": true,
          "conditions": [
            {"attribute": "country", "op": "eq", "value": "CN"},
            {"attribute": "plan", "op": "eq", "value": "pro"}
          ]
        }
      ]
    },
    {
      "key": "in-flag",
      "enabled": true,
      "default": false,
      "rules": [
        {
          "id": "sea",
          "value": true,
          "conditions": [
            {"attribute": "country", "op": "in", "value": ["CN", "SG", "JP"]}
          ]
        }
      ]
    },
    {
      "key": "empty-rules",
      "enabled": true,
      "default": true,
      "rules": []
    }
  ]
}`

func strptr(s string) *string { return &s }

func TestEvaluateFlags(t *testing.T) {
	tests := []struct {
		name    string
		config  string
		context string
		key     string
		want    FlagResult
	}{
		{
			name:    "disabled flag always false",
			config:  validConfig,
			context: `{"country":"CN","plan":"pro"}`,
			key:     "disabled-flag",
			want:    FlagResult{Key: "disabled-flag", Value: false, Reason: "disabled", RuleID: nil},
		},
		{
			name:    "eq rule matches all conditions",
			config:  validConfig,
			context: `{"country":"CN","plan":"pro"}`,
			key:     "eq-flag",
			want:    FlagResult{Key: "eq-flag", Value: true, Reason: "rule", RuleID: strptr("cn-pro")},
		},
		{
			name:    "eq rule one condition fails falls to default",
			config:  validConfig,
			context: `{"country":"CN","plan":"free"}`,
			key:     "eq-flag",
			want:    FlagResult{Key: "eq-flag", Value: false, Reason: "default", RuleID: nil},
		},
		{
			name:    "missing attribute fails condition",
			config:  validConfig,
			context: `{"country":"CN"}`,
			key:     "eq-flag",
