			config:     `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[]}]}`,
			context:    `{"a":1}`,
			key:        "nope",
			wantErrSub: `上下文属性 "a" 的值必须是字符串`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
