			config:     `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[{"id":"r","value":true,"conditions":[{"attribute":"a","op":"in","value":"x"}]}]}]}`,
			context:    `{}`,
			key:        "f",
			wantErrSub: "conditions[0].value: in 时必须是非空字符串数组",
		},
		{
			name:       "in value element not string",
