			context:    `{}`,
			key:        "f",
			wantErrSub: "conditions[0].value[1]: 必须是字符串",
		},
		{
			name:       "unselected disabled flag still validated",
			config:     `{"flags":[{"key":"other","enabled":false,"default":true,"rules":[{"id":"r","value":true,"conditions":[]}]}]}`,
			context:    `{}`,
			key:        "missing-key",
			wantErrSub: "条件组不能为空",
