					}
				}
				conds = append(conds, cond)
			}
			rules = append(rules, flagRule{ID: id, Value: value, Conditions: conds})
		}
		result[key] = featureFlag{Key: key, Enabled: enabled, Default: def, Rules: rules}
	}
	return result, nil
}

